create extension if not exists "pgcrypto";
create type match_status as enum ('SCHEDULED','LIVE','FINISHED','POSTPONED','CANCELLED');
create type prediction_status as enum ('PENDING','LIVE_CORRECT','LIVE_INCORRECT','WON','LOST','VOID');
create table profiles (id uuid primary key references auth.users on delete cascade, username text unique not null, avatar_url text, created_at timestamptz not null default now());
create table competitions (id uuid primary key default gen_random_uuid(), provider text not null, provider_id text not null, name text not null, country text, season int not null, competition_type text not null, unique(provider,provider_id,season));
create table competition_rounds (id uuid primary key default gen_random_uuid(), competition_id uuid not null references competitions on delete cascade, name text not null, round_number int, stage_type text not null);
create table teams (id uuid primary key default gen_random_uuid(), provider text not null, provider_id text not null, name text not null, short_name text, logo_url text, unique(provider,provider_id));
create table matches (id uuid primary key default gen_random_uuid(), provider text not null, provider_id text not null, competition_id uuid not null references competitions, round_id uuid references competition_rounds, home_team_id uuid not null references teams, away_team_id uuid not null references teams, kickoff_at timestamptz not null, status match_status not null default 'SCHEDULED', home_score int, away_score int, last_synced_at timestamptz, unique(provider,provider_id), check(home_team_id<>away_team_id));
create table prediction_types (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, description text, answer_type text not null, points int not null check(points>=0), enabled boolean not null default true, required_statistic text);
create table match_prediction_types (id uuid primary key default gen_random_uuid(), match_id uuid not null references matches on delete cascade, prediction_type_id uuid not null references prediction_types, enabled boolean not null default true, lock_at timestamptz not null, unique(match_id,prediction_type_id));
create table predictions (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles on delete cascade, match_id uuid not null references matches on delete cascade, prediction_type_id uuid not null references prediction_types, selected_option_id uuid, value_json jsonb not null, submitted_at timestamptz not null default now(), updated_at timestamptz not null default now(), locked_at timestamptz, status prediction_status not null default 'PENDING', unique(user_id,match_id,prediction_type_id));
create table prediction_results (id uuid primary key default gen_random_uuid(), prediction_id uuid not null unique references predictions on delete cascade, status prediction_status not null, correct boolean, points_awarded int not null default 0, evaluated_at timestamptz not null default now(), evaluation_version int not null, unique(prediction_id,evaluation_version));
alter table profiles enable row level security; alter table predictions enable row level security;
create policy "profiles readable" on profiles for select using (true);
create policy "own profile" on profiles for update using (auth.uid()=id);
create policy "own predictions read" on predictions for select using (auth.uid()=user_id);
create policy "own predictions insert" on predictions for insert with check (auth.uid()=user_id and now() < (select kickoff_at from matches where id=match_id));
create policy "own predictions update before kickoff" on predictions for update using (auth.uid()=user_id and now() < (select kickoff_at from matches where id=match_id));
insert into prediction_types(code,name,answer_type,points,required_statistic) values ('MATCH_WINNER','Match winner','choice',3,null),('EXACT_SCORE','Exact score','score',8,null),('BOTH_TEAMS_SCORE','Both teams score','choice',2,null),('FIRST_SCORER','First goalscorer','player',6,'events'),('ANYTIME_SCORER','Anytime scorer','player',4,'events'),('MOST_CORNERS','Most corners','team',3,'corners');
